fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // The limit for rsplitn is number of parts, which is maxsplit + 1
    let limit = (maxsplit as usize) + 1;
    let sep_str = sep.as_str();

    a.into_iter()
        .map(|s| {
            // Perform at most `limit - 1` splits from the right,
            // which yields at most `limit` substrings.
            let mut parts: Vec<String> = s
                .rsplitn(limit, sep_str)
                .map(|substr| substr.to_string())
                .collect();
            // rsplitn yields substrings from right to left, so reverse
            // to restore the left-to-right order.
            parts.reverse();
            parts
        })
        .collect()
}